window.BANCO = window.BANCO || [];
window.BANCO.push({"id": "tema2", "nombre": "Tema 2 · La Corona", "bloques": [{"id": "t2-sucesion", "nombre": "Sucesión, regencia y tutela (arts. 57 a 60)"}, {"id": "t2-rey", "nombre": "El Rey: estatuto, funciones y refrendo (arts. 56 y 61 a 65)"}], "calendarios": {}, "casos": [], "preguntas": [{"id": "ce-071", "origen": "otras", "test": "Test exámenes", "n": 6, "enunciado": "El artículo 56 de la CE establece que el Rey asume la más alta representación del Estado español en las relaciones internacionales, y especialmente:", "opciones": ["Con las naciones iberoamericanas.", "Con las naciones de la Unión Europea.", "Con las naciones de su comunidad cultural.", "Con las naciones de su comunidad histórica."], "bloque": "t2-rey", "precepto": "Artículo 56.1 CE", "correcta": 3, "justificaciones": ["No. «Iberoamericanas» es la palabra del artículo 11.3, sobre tratados de doble nacionalidad, no del 56.1.", "No. La Unión Europea no aparece en el artículo 56.", "No. «Comunidad cultural» es la variante falsa más repetida: el texto dice «histórica».", "Es esta. Literal del 56.1: «especialmente con las naciones de su comunidad histórica»."], "arts": [56], "citas": [{"texto": "«El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones, asume la más alta representación del Estado español en las relaciones internacionales, especialmente con las naciones de su comunidad histórica, y ejerce las funciones que le atribuyen expresamente la Constitución y las leyes.»", "fuente": "Artículo 56.1 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "ojo": "Comunidad HISTÓRICA, no cultural. Es un cambio de una palabra y es la trampa habitual."}, {"id": "ce-072", "origen": "otras", "test": "Test exámenes", "n": 7, "enunciado": "A tenor de lo establecido en el artículo 63 de la CE:", "opciones": ["Al Rey corresponde manifestar el consentimiento del Estado para obligarse internacionalmente por medio de tratados, de conformidad con la Constitución y las leyes.", "El Rey acredita a los embajadores y otros representantes diplomáticos, previa autorización de las Cortes Generales.", "Al Rey corresponde, previa autorización del Presidente del Gobierno, declarar la guerra y hacer la paz.", "Los representantes extranjeros en España están acreditados ante él, si así lo establece la Constitución en sus países de origen."], "bloque": "t2-rey", "precepto": "Artículo 63 CE", "correcta": 0, "justificaciones": ["Es esta. Reproduce el 63.2 palabra por palabra.", "No. El 63.1 no exige ninguna autorización de las Cortes para acreditar embajadores.", "No. La guerra y la paz exigen autorización previa de las Cortes Generales, no del Presidente del Gobierno (63.3).", "No. El 63.1 dice, sin condición alguna, que los representantes extranjeros en España «están acreditados ante él»."], "arts": [63], "citas": [{"texto": "«1. El Rey acredita a los embajadores y otros representantes diplomáticos. Los representantes extranjeros en España están acreditados ante él. 2. Al Rey corresponde manifestar el consentimiento del Estado para obligarse internacionalmente por medio de tratados, de conformidad con la Constitución y las leyes. 3. Al Rey corresponde, previa autorización de las Cortes Generales, declarar la guerra y hacer la paz.»", "fuente": "Artículo 63 CE"}], "truco": "El artículo 63 en tres apartados: 63.1 embajadores · 63.2 consentimiento en tratados · 63.3 guerra y paz. Solo el tercero necesita autorización de las Cortes."}, {"id": "ce-073", "origen": "otras", "test": "Test exámenes", "n": 11, "enunciado": "Según la Constitución Española, ¿a quién corresponde manifestar el consentimiento del Estado para obligarse internacionalmente por medio de tratados?:", "opciones": ["Al Rey.", "Al Presidente del Gobierno.", "Al Congreso de los Diputados.", "A las Cortes Generales."], "bloque": "t2-rey", "precepto": "Artículo 63 CE", "correcta": 0, "justificaciones": ["Es esta. El 63.2 atribuye al Rey manifestar el consentimiento del Estado para obligarse internacionalmente por medio de tratados.", "No. El Presidente del Gobierno dirige la política exterior (97), pero no manifiesta el consentimiento del Estado.", "No. El Congreso no interviene por sí solo: la autorización del artículo 94 es de las Cortes Generales.", "No. Las Cortes autorizan previamente en los casos del artículo 94, pero quien manifiesta el consentimiento es el Rey."], "arts": [63], "citas": [{"texto": "«1. El Rey acredita a los embajadores y otros representantes diplomáticos. Los representantes extranjeros en España están acreditados ante él. 2. Al Rey corresponde manifestar el consentimiento del Estado para obligarse internacionalmente por medio de tratados, de conformidad con la Constitución y las leyes. 3. Al Rey corresponde, previa autorización de las Cortes Generales, declarar la guerra y hacer la paz.»", "fuente": "Artículo 63 CE"}], "truco": "Autorizar y manifestar el consentimiento son actos distintos: las Cortes AUTORIZAN (art. 94), el Rey MANIFIESTA (art. 63.2)."}, {"id": "ce-074", "origen": "oficiales", "test": "INAP mar 2022", "n": 2, "enunciado": "Señale la respuesta correcta en relación con la Regencia:", "opciones": ["Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento, acumulando los cargos de Regente y tutor.", "Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por el Senado, y se compondrá de tres o cinco personas.", "La Reina consorte o el consorte de la Reina no podrán asumir funciones constitucionales, salvo lo dispuesto para la Regencia.", "Para ejercer la Regencia es preciso ser español y mayor de veintiún años."], "bloque": "t2-sucesion", "precepto": "Artículo 58 CE; Artículo 59 CE; Artículo 60 CE", "correcta": 2, "justificaciones": ["No. El 60.1 solo permite acumular Regente y tutor en el padre, la madre o los ascendientes directos del Rey.", "No. La Regencia la nombran las Cortes Generales, no el Senado, y se compone de una, tres o cinco personas (59.3).", "Es esta. Es el artículo 58 literal: la Reina consorte o el consorte de la Reina no pueden asumir funciones constitucionales, y la única salvedad es la Regencia.", "No. El 59.4 solo pide ser español y mayor de edad. Los veintiún años no aparecen en ningún sitio."], "arts": [58, 59, 60], "citas": [{"texto": "«La Reina consorte o el consorte de la Reina no podrán asumir funciones constitucionales, salvo lo dispuesto para la Regencia.»", "fuente": "Artículo 58 CE"}, {"texto": "«1. Cuando el Rey fuere menor de edad, el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona, según el orden establecido en la Constitución, entrará a ejercer inmediatamente la Regencia y la ejercerá durante el tiempo de la minoría de edad del Rey.»«2. Si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero de la Corona, si fuere mayor de edad. Si no lo fuere, se procederá de la manera prevista en el apartado anterior, hasta que el Príncipe heredero alcance la mayoría de edad.»«3. Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales, y se compondrá de una, tres o cinco personas.» · «4. Para ejercer la Regencia es preciso ser español y mayor de edad.» · «5. La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.»", "fuente": "Artículo 59 CE"}, {"texto": "«1. Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos. En su defecto, lo nombrarán las Cortes Generales, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey.»«2. El ejercicio de la tutela es también incompatible con el de todo cargo o representación política.»", "fuente": "Artículo 60 CE"}]}, {"id": "ce-075", "origen": "otras", "test": "Test exámenes", "n": 20, "enunciado": "Señale quién refrenda el acto del Rey por el que se nombra al Presidente del Gobierno tras la votación de investidura:", "opciones": ["El Ministro de Administraciones Públicas en funciones.", "El Presidente del Congreso de los Diputados.", "El Presidente del Senado.", "Los Presidentes del Congreso y del Senado."], "bloque": "t2-rey", "precepto": "Artículo 64 CE", "correcta": 1, "justificaciones": ["No. No existe refrendo ministerial para el nombramiento del Presidente del Gobierno.", "Es esta. La regla general del refrendo es el Presidente del Gobierno, pero la propuesta y el nombramiento del Presidente del Gobierno son una de las dos excepciones que refrenda el Presidente del Congreso.", "No. El Presidente del Senado no refrenda nunca ningún acto del Rey.", "No. Los dos juntos tampoco: el 64.1 nombra únicamente al Presidente del Congreso."], "arts": [64], "citas": [{"texto": "«1. Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso. 2. De los actos del Rey serán responsables las personas que los refrenden.»", "fuente": "Artículo 64 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "El Presidente del Congreso refrenda exactamente dos cosas: (1) la propuesta y el nombramiento del Presidente del Gobierno y (2) la disolución del artículo 99. Todo lo demás, Presidente del Gobierno o ministros competentes."}, {"id": "ce-076", "origen": "otras", "test": "Test exámenes", "n": 24, "enunciado": "Para ejercer la Regencia es preciso, según nuestra normativa constitucional:", "opciones": ["Ser mayor de edad.", "Ser español y mayor de edad.", "Ser español de nacimiento y mayor de edad.", "Ser mayor de edad y nacional de un Estado miembro de la Unión Europea."], "bloque": "t2-sucesion", "precepto": "Artículo 59 CE; Artículo 60 CE", "correcta": 1, "justificaciones": ["No. Le falta el requisito de ser español.", "Es esta. Literal del 59.4: ser español y mayor de edad. Nada más.", "No. «De nacimiento» es el requisito del tutor (60.1), no del Regente.", "No. La Constitución no admite la nacionalidad de otro Estado miembro para ejercer la Regencia."], "arts": [59, 60], "citas": [{"texto": "«1. Cuando el Rey fuere menor de edad, el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona, según el orden establecido en la Constitución, entrará a ejercer inmediatamente la Regencia y la ejercerá durante el tiempo de la minoría de edad del Rey.»«2. Si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero de la Corona, si fuere mayor de edad. Si no lo fuere, se procederá de la manera prevista en el apartado anterior, hasta que el Príncipe heredero alcance la mayoría de edad.»«3. Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales, y se compondrá de una, tres o cinco personas.» · «4. Para ejercer la Regencia es preciso ser español y mayor de edad.» · «5. La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.»", "fuente": "Artículo 59 CE"}, {"texto": "«1. Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos. En su defecto, lo nombrarán las Cortes Generales, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey.»«2. El ejercicio de la tutela es también incompatible con el de todo cargo o representación política.»", "fuente": "Artículo 60 CE"}], "ojo": "En el documento original esta pregunta trae dos opciones marcadas con la misma letra y le falta la cuarta. Se ha corregido la numeración sin tocar los textos.", "truco": "Regente: español + mayor de edad. Tutor: español DE NACIMIENTO + mayor de edad. El tutor es el que tiene el requisito más exigente."}, {"id": "ce-077", "origen": "otras", "test": "Test exámenes", "n": 25, "enunciado": "De conformidad con el artículo 62 de la Constitución corresponde al Rey:", "opciones": ["Convocar y disolver las Cortes generales y convocar elecciones en los términos previstos en la Constitución.", "Sancionar y promulgar las leyes y ordenar la publicación de las Órdenes Ministeriales.", "El mando supremo de los Cuerpos y Fuerzas de Seguridad del Estado.", "Ejercer el derecho de gracia de acuerdo con los Tratados Internacionales."], "bloque": "t2-rey", "precepto": "Artículo 62 CE", "correcta": 0, "justificaciones": ["Es esta. Es el 62.b) literal: convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución.", "No. El 62.a) es «sancionar y promulgar las leyes». El Rey no ordena la publicación de las órdenes ministeriales.", "No. El 62.h) le da el mando supremo de las Fuerzas Armadas, no de los Cuerpos y Fuerzas de Seguridad del Estado.", "No. El 62.i) dice «con arreglo a la ley», no con arreglo a los tratados internacionales."], "arts": [62], "citas": [{"texto": "«Corresponde al Rey: a) Sancionar y promulgar las leyes. b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución. c) Convocar a referéndum en los casos previstos en la Constitución. d) Proponer el candidato a Presidente del Gobierno y, en su caso, nombrarlo, así como poner fin a sus funciones en los términos previstos en la Constitución. e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente. f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes. g) Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno. h) El mando supremo de las Fuerzas Armadas. i) Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales. j) El Alto Patronazgo de las Reales Academias.»", "fuente": "Artículo 62 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "El artículo 62 tiene diez letras, de la a) a la j). Las trampas cambian siempre una palabra: Fuerzas Armadas → Cuerpos de Seguridad, «con arreglo a la ley» → tratados, «su Presidente» → el Congreso."}, {"id": "ce-078", "origen": "otras", "test": "Test exámenes", "n": 31, "enunciado": "Conforme con el artículo 64 de la CE, de los actos de Rey serán responsables:", "opciones": ["El tutor del Rey, en su caso.", "Las personas que los refrenden.", "Los Presidentes del Congreso de los Diputados y del Senado en todo caso.", "Los Presidentes de las Comunidades Autónomas."], "bloque": "t2-rey", "precepto": "Artículo 64 CE; Artículo 56.3 CE", "correcta": 1, "justificaciones": ["No. El tutor no responde de los actos del Rey: su función es la guarda del Rey menor.", "Es esta. Literal del 64.2: de los actos del Rey son responsables las personas que los refrendan.", "No. El Presidente del Congreso solo responde de los dos actos que él refrenda, no «en todo caso».", "No. Los Presidentes de las Comunidades Autónomas no refrendan actos del Rey."], "arts": [56, 64], "citas": [{"texto": "«1. Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso. 2. De los actos del Rey serán responsables las personas que los refrenden.»", "fuente": "Artículo 64 CE"}, {"texto": "«La persona del Rey es inviolable y no está sujeta a responsabilidad. Sus actos estarán siempre refrendados en la forma establecida en el artículo 64, careciendo de validez sin dicho refrendo, salvo lo dispuesto en el artículo 65, 2.»", "fuente": "Artículo 56.3 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "El binomio clave: el Rey es inviolable y no responde (56.3), y precisamente por eso responde quien refrenda (64.2). Sin refrendo el acto no vale, salvo el 65.2."}, {"id": "ce-079", "origen": "otras", "test": "Test exámenes", "n": 44, "enunciado": "Conforme a lo establecido en el Título II de la CE relativo a la Corona, señale la respuesta correcta:", "opciones": ["En la sucesión no existe distinción alguna de preferencia entre los hijos varones y las mujeres.", "Se configura como un órgano del Estado; el Rey es el Jefe del Estado.", "Cualquier duda que se plantee sobre abdicaciones o renuncias a la Corona se resolverá por ley ordinaria.", "Para ejercer la tutela no es preciso ser español, salvo en ciertos casos."], "bloque": "t2-sucesion", "precepto": "Artículo 56.1 CE; Artículo 57.1 CE; Artículo 57.5 CE; Artículo 60 CE", "correcta": 1, "justificaciones": ["No. Falso: el 57.1 prefiere, en el mismo grado, el varón a la mujer. Sí hay distinción de preferencia.", "Es esta. El 56.1 empieza diciendo «El Rey es el Jefe del Estado»: la Corona es un órgano del Estado con su propio Título II.", "No. Las dudas sobre abdicaciones y renuncias se resuelven por LEY ORGÁNICA (57.5), no por ley ordinaria.", "No. El tutor ha de ser español de nacimiento (60.1): el requisito es más estricto, no más laxo."], "arts": [56, 57, 60], "citas": [{"texto": "«El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones, asume la más alta representación del Estado español en las relaciones internacionales, especialmente con las naciones de su comunidad histórica, y ejerce las funciones que le atribuyen expresamente la Constitución y las leyes.»", "fuente": "Artículo 56.1 CE"}, {"texto": "«La Corona de España es hereditaria en los sucesores de S. M. Don Juan Carlos I de Borbón, legítimo heredero de la dinastía histórica. La sucesión en el trono seguirá el orden regular de primogenitura y representación, siendo preferida siempre la línea anterior a las posteriores; en la misma línea, el grado más próximo al más remoto; en el mismo grado, el varón a la mujer, y en el mismo sexo, la persona de más edad a la de menos.»", "fuente": "Artículo 57.1 CE"}, {"texto": "«Las abdicaciones y renuncias y cualquier duda de hecho o de derecho que ocurra en el orden de sucesión a la Corona se resolverán por una ley orgánica.»", "fuente": "Artículo 57.5 CE"}, {"texto": "«1. Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos. En su defecto, lo nombrarán las Cortes Generales, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey.»«2. El ejercicio de la tutela es también incompatible con el de todo cargo o representación política.»", "fuente": "Artículo 60 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-080", "origen": "otras", "test": "Test exámenes", "n": 48, "enunciado": "De acuerdo con el artículo 65 de la CE, ¿quién nombra a los miembros de la Casa Real?:", "opciones": ["El Presidente del Gobierno.", "El Presidente del Congreso.", "El Rey.", "Los Ministros, según su competencia."], "bloque": "t2-rey", "precepto": "Artículo 65 CE", "correcta": 2, "justificaciones": ["No. El Presidente del Gobierno no interviene en el nombramiento de la Casa del Rey.", "No. El Presidente del Congreso tampoco.", "Es esta. Literal del 65.2: el Rey nombra y releva libremente a los miembros civiles y militares de su Casa.", "No. Los ministros no nombran a los miembros de la Casa del Rey."], "arts": [65], "citas": [{"texto": "«1. El Rey recibe de los Presupuestos del Estado una cantidad global para el sostenimiento de su Familia y Casa, y distribuye libremente la misma. 2. El Rey nombra y releva libremente a los miembros civiles y militares de su Casa.»", "fuente": "Artículo 65 CE"}], "truco": "El 65.2 es la ÚNICA excepción al refrendo: el 56.3 dice «salvo lo dispuesto en el artículo 65, 2». Nombrar a su Casa es el único acto verdaderamente libre del Rey."}, {"id": "ce-081", "origen": "otras", "test": "Test exámenes", "n": 49, "enunciado": "De acuerdo con la CE, ¿a quién corresponde sancionar las leyes?:", "opciones": ["Al Gobierno.", "Al Rey.", "A las Cortes Generales.", "Al Congreso de los Diputados."], "bloque": "t2-rey", "precepto": "Artículo 62 CE", "correcta": 1, "justificaciones": ["No. El Gobierno tiene iniciativa legislativa (art. 87.1), pero no sanciona.", "Es esta. El 62.a) atribuye al Rey sancionar y promulgar las leyes.", "No. Las Cortes Generales aprueban las leyes; la sanción es del Rey.", "No. El Congreso tampoco sanciona: aprueba, junto con el Senado."], "arts": [62], "citas": [{"texto": "«Corresponde al Rey: a) Sancionar y promulgar las leyes. b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución. c) Convocar a referéndum en los casos previstos en la Constitución. d) Proponer el candidato a Presidente del Gobierno y, en su caso, nombrarlo, así como poner fin a sus funciones en los términos previstos en la Constitución. e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente. f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes. g) Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno. h) El mando supremo de las Fuerzas Armadas. i) Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales. j) El Alto Patronazgo de las Reales Academias.»", "fuente": "Artículo 62 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "Cuatro verbos, dos sujetos: las Cortes APRUEBAN; el Rey SANCIONA, PROMULGA y ordena PUBLICAR, y lo hace en el plazo de quince días (art. 91)."}, {"id": "ce-082", "origen": "otras", "test": "Test exámenes", "n": 51, "enunciado": "La abdicación de S.M el Rey Juan Carlos I, conforme a lo dispuesto en la CE, se produjo mediante:", "opciones": ["Real Decreto-ley.", "Real Decreto del Presidente del Gobierno.", "Ley Orgánica.", "Acuerdo del Consejo de Ministros."], "bloque": "t2-sucesion", "precepto": "Artículo 57.5 CE", "correcta": 2, "justificaciones": ["No. El real decreto-ley es una norma del Gobierno para casos de extraordinaria y urgente necesidad: no cabe aquí.", "No. Un real decreto del Presidente del Gobierno no tiene rango de ley.", "Es esta. El 57.5 reserva a la ley orgánica las abdicaciones y renuncias. La de Juan Carlos I fue la Ley Orgánica 3/2014, de 18 de junio.", "No. Un acuerdo del Consejo de Ministros tampoco."], "arts": [57], "citas": [{"texto": "«Las abdicaciones y renuncias y cualquier duda de hecho o de derecho que ocurra en el orden de sucesión a la Corona se resolverán por una ley orgánica.»", "fuente": "Artículo 57.5 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "Todo lo que toca el orden sucesorio (abdicaciones, renuncias y cualquier duda de hecho o de derecho) se resuelve por LEY ORGÁNICA. El 57.5 no admite otra vía."}, {"id": "ce-083", "origen": "otras", "test": "Test exámenes", "n": 59, "enunciado": "De conformidad con el artículo 59.3 de la CE, si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales y se compondrá de:", "opciones": ["Un máximo de dos personas.", "Un máximo de cuatro personas.", "Dos o cuatro personas.", "Una, tres o cinco personas."], "bloque": "t2-sucesion", "precepto": "Artículo 59 CE", "correcta": 3, "justificaciones": ["No. «Un máximo de dos personas» no está en el precepto, y además sería un número par.", "No. «Un máximo de cuatro» tampoco aparece.", "No. «Dos o cuatro» son números pares: el 59.3 solo admite impares.", "Es esta. Literal del 59.3: la nombran las Cortes Generales y se compone de una, tres o cinco personas."], "arts": [59], "citas": [{"texto": "«1. Cuando el Rey fuere menor de edad, el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona, según el orden establecido en la Constitución, entrará a ejercer inmediatamente la Regencia y la ejercerá durante el tiempo de la minoría de edad del Rey.»«2. Si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero de la Corona, si fuere mayor de edad. Si no lo fuere, se procederá de la manera prevista en el apartado anterior, hasta que el Príncipe heredero alcance la mayoría de edad.»«3. Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales, y se compondrá de una, tres o cinco personas.» · «4. Para ejercer la Regencia es preciso ser español y mayor de edad.» · «5. La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.»", "fuente": "Artículo 59 CE"}], "ojo": "Siempre número impar: una, tres o cinco."}, {"id": "ce-084", "origen": "otras", "test": "Test exámenes", "n": 66, "enunciado": "Según el artículo 58 de la CE, salvo lo dispuesto para la Regencia, la Reina consorte o el consorte de la Reina no podrán asumir funciones:", "opciones": ["Constitucionales.", "Políticas.", "Representativas.", "Profesionales."], "bloque": "t2-sucesion", "precepto": "Artículo 58 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del artículo 58: no podrán asumir funciones constitucionales.", "No. «Políticas» no es la palabra que usa el artículo 58.", "No. «Representativas» tampoco.", "No. «Profesionales» tampoco."], "arts": [58], "citas": [{"texto": "«La Reina consorte o el consorte de la Reina no podrán asumir funciones constitucionales, salvo lo dispuesto para la Regencia.»", "fuente": "Artículo 58 CE"}], "truco": "La palabra es CONSTITUCIONALES, y la salvedad es una sola: la Regencia."}, {"id": "ce-085", "origen": "otras", "test": "Test exámenes", "n": 71, "enunciado": "Señale la afirmación correcta en relación con el ejercicio de la tutela del Rey:", "opciones": ["Es compatible únicamente con el cargo de Presidente del Gobierno.", "Es compatible únicamente con aquellos cargos políticos determinados por las Cortes por mayoría de dos tercios de cada Cámara.", "Es incompatible únicamente con todo cargo o representación política en las Comunidades Autónomas.", "Es incompatible con todo cargo o representación política."], "bloque": "t2-sucesion", "precepto": "Artículo 60 CE", "correcta": 3, "justificaciones": ["No. No hay ninguna compatibilidad con el cargo de Presidente del Gobierno.", "No. Las Cortes no pueden habilitar cargos compatibles: la incompatibilidad del 60.2 es absoluta.", "No. No se limita a las Comunidades Autónomas: el precepto dice «todo cargo o representación política».", "Es esta. Literal del 60.2: el ejercicio de la tutela es incompatible con el de todo cargo o representación política."], "arts": [60], "citas": [{"texto": "«1. Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos. En su defecto, lo nombrarán las Cortes Generales, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey.»«2. El ejercicio de la tutela es también incompatible con el de todo cargo o representación política.»", "fuente": "Artículo 60 CE"}], "truco": "El 60.2 dice «todo». Cualquier opción que introduzca un «únicamente» o una excepción es falsa."}, {"id": "ce-086", "origen": "otras", "test": "Test exámenes", "n": 77, "enunciado": "Según el Título II de la Constitución, señale la respuesta correcta sobre los actos del Rey que deben ser refrendados por el Presidente del Congreso:", "opciones": ["La propuesta y nombramiento del Presidente del Gobierno.", "La declaración de la guerra y la paz.", "El nombramiento del personal civil y militar de su casa.", "La convocatoria de referéndum."], "bloque": "t2-rey", "precepto": "Artículo 64 CE", "correcta": 0, "justificaciones": ["Es esta. Los dos únicos actos que refrenda el Presidente del Congreso son la propuesta y el nombramiento del Presidente del Gobierno y la disolución del artículo 99.", "No. La declaración de guerra y la paz (63.3) las refrenda el Presidente del Gobierno; lo que hace falta es autorización de las Cortes.", "No. El nombramiento del personal civil y militar de su Casa (65.2) es el único acto del Rey que no necesita refrendo alguno.", "No. La convocatoria de referéndum (62.c) la refrenda el Presidente del Gobierno."], "arts": [64], "citas": [{"texto": "«1. Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso. 2. De los actos del Rey serán responsables las personas que los refrenden.»", "fuente": "Artículo 64 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-087", "origen": "otras", "test": "Test exámenes", "n": 82, "enunciado": "Entre las competencias atribuidas constitucionalmente al Rey se encuentra:", "opciones": ["Proponer el nombramiento de los miembros del Gobierno.", "Proponer la disolución de las Cortes Generales.", "La autorización de indultos generales.", "Expedir los decretos acordados en Consejo de Ministros."], "bloque": "t2-rey", "precepto": "Artículo 62 CE", "correcta": 3, "justificaciones": ["No. El Rey no propone ministros: los nombra y separa a propuesta de su Presidente (62.e).", "No. La disolución del artículo 115 la propone el Presidente del Gobierno; el Rey la decreta.", "No. El 62.i) prohíbe expresamente que el derecho de gracia autorice indultos generales.", "Es esta. Es el 62.f) literal: expedir los decretos acordados en el Consejo de Ministros."], "arts": [62], "citas": [{"texto": "«Corresponde al Rey: a) Sancionar y promulgar las leyes. b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución. c) Convocar a referéndum en los casos previstos en la Constitución. d) Proponer el candidato a Presidente del Gobierno y, en su caso, nombrarlo, así como poner fin a sus funciones en los términos previstos en la Constitución. e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente. f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes. g) Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno. h) El mando supremo de las Fuerzas Armadas. i) Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales. j) El Alto Patronazgo de las Reales Academias.»", "fuente": "Artículo 62 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "El Rey casi nunca «propone»: lo único que propone es el candidato a Presidente del Gobierno (62.d). En todo lo demás otros proponen y él nombra, expide o decreta."}, {"id": "ce-088", "origen": "otras", "test": "Test exámenes", "n": 88, "enunciado": "Según el Título II de la Constitución Española relativo a la Corona:", "opciones": ["La Regencia se ejercerá por mandato constitucional y en nombre del Rey.", "Las abdicaciones y renuncias en el orden sucesorio se resolverán por ley ordinaria.", "El Príncipe heredero podrá asumir la Regencia durante su minoría de edad.", "La Regencia podrá ejercerse por nacionales de cualquier Estado."], "bloque": "t2-sucesion", "precepto": "Artículo 59 CE; Artículo 57.5 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 59.5: la Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.", "No. Las abdicaciones y renuncias se resuelven por ley orgánica (57.5), no ordinaria.", "No. El Príncipe heredero solo asume la Regencia si es mayor de edad (59.2); si es menor, se aplica el 59.1.", "No. Para ejercer la Regencia es preciso ser español (59.4)."], "arts": [57, 59], "citas": [{"texto": "«1. Cuando el Rey fuere menor de edad, el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona, según el orden establecido en la Constitución, entrará a ejercer inmediatamente la Regencia y la ejercerá durante el tiempo de la minoría de edad del Rey.»«2. Si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero de la Corona, si fuere mayor de edad. Si no lo fuere, se procederá de la manera prevista en el apartado anterior, hasta que el Príncipe heredero alcance la mayoría de edad.»«3. Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales, y se compondrá de una, tres o cinco personas.» · «4. Para ejercer la Regencia es preciso ser español y mayor de edad.» · «5. La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.»", "fuente": "Artículo 59 CE"}, {"texto": "«Las abdicaciones y renuncias y cualquier duda de hecho o de derecho que ocurra en el orden de sucesión a la Corona se resolverán por una ley orgánica.»", "fuente": "Artículo 57.5 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-089", "origen": "otras", "test": "Test exámenes", "n": 89, "enunciado": "Según la Constitución Española, es competencia del Rey:", "opciones": ["Refrendar los actos del Presidente de Gobierno.", "Previa autorización del Presidente de Gobierno, declarar la guerra y hacer la paz.", "El Alto Patronazgo de las Reales Academias.", "Sancionar y publicar las leyes."], "bloque": "t2-rey", "precepto": "Artículo 62 CE; Artículo 63 CE; Artículo 64 CE", "correcta": 2, "justificaciones": ["No. El Rey no refrenda: es refrendado. Refrendan el Presidente del Gobierno, los ministros competentes o el Presidente del Congreso (64.1).", "No. La autorización para declarar la guerra y hacer la paz es de las Cortes Generales, no del Presidente del Gobierno (63.3).", "Es esta. Es el 62.j) literal: el Alto Patronazgo de las Reales Academias.", "No. El 62.a) dice «sancionar y PROMULGAR» las leyes. Ordenar su publicación es cosa del artículo 91."], "arts": [62, 63, 64], "citas": [{"texto": "«Corresponde al Rey: a) Sancionar y promulgar las leyes. b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución. c) Convocar a referéndum en los casos previstos en la Constitución. d) Proponer el candidato a Presidente del Gobierno y, en su caso, nombrarlo, así como poner fin a sus funciones en los términos previstos en la Constitución. e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente. f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes. g) Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno. h) El mando supremo de las Fuerzas Armadas. i) Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales. j) El Alto Patronazgo de las Reales Academias.»", "fuente": "Artículo 62 CE"}, {"texto": "«1. El Rey acredita a los embajadores y otros representantes diplomáticos. Los representantes extranjeros en España están acreditados ante él. 2. Al Rey corresponde manifestar el consentimiento del Estado para obligarse internacionalmente por medio de tratados, de conformidad con la Constitución y las leyes. 3. Al Rey corresponde, previa autorización de las Cortes Generales, declarar la guerra y hacer la paz.»", "fuente": "Artículo 63 CE"}, {"texto": "«1. Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso. 2. De los actos del Rey serán responsables las personas que los refrenden.»", "fuente": "Artículo 64 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "Sancionar, promulgar y ordenar publicar son tres actos distintos, y el 62.a) solo recoge los dos primeros."}, {"id": "ce-090", "origen": "otras", "test": "Test exámenes", "n": 95, "enunciado": "La Constitución Española establece que extinguidas todas las líneas llamadas en Derecho a la sucesión a la Corona:", "opciones": ["Las Cortes Generales proveerán a la sucesión en la Corona en la forma en que más convenga a los intereses de España.", "Ejercerá las funciones la Reina consorte o el consorte de la Reina.", "El Presidente del Gobierno proveerá a la sucesión en la Corona en la forma que más convenga a los intereses de España.", "Ejercerá sus funciones el tutor que hubiera nombrado el Rey difunto."], "bloque": "t2-sucesion", "precepto": "Artículo 57.3 CE; Artículo 58 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 57.3: extinguidas todas las líneas llamadas en Derecho, proveen las Cortes Generales, en la forma que más convenga a los intereses de España.", "No. El artículo 58 se lo prohíbe expresamente a la Reina consorte y al consorte de la Reina, salvo para la Regencia.", "No. El Presidente del Gobierno no interviene en la sucesión a la Corona.", "No. El tutor cuida del Rey menor; no provee a la sucesión."], "arts": [57, 58], "citas": [{"texto": "«Extinguidas todas las líneas llamadas en Derecho, las Cortes Generales proveerán a la sucesión en la Corona en la forma que más convenga a los intereses de España.»", "fuente": "Artículo 57.3 CE"}, {"texto": "«La Reina consorte o el consorte de la Reina no podrán asumir funciones constitucionales, salvo lo dispuesto para la Regencia.»", "fuente": "Artículo 58 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-091", "origen": "otras", "test": "Test exámenes", "n": 96, "enunciado": "Según el artículo 59 de la Constitución Española, si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia:", "opciones": ["El Presidente del Gobierno.", "El Presidente de las Cortes Generales.", "La Princesa heredera de la Corona, si fuese mayor de edad.", "La Princesa heredera de la Corona, aunque fuese menor de edad."], "bloque": "t2-sucesion", "precepto": "Artículo 59 CE", "correcta": 2, "justificaciones": ["No. El Presidente del Gobierno no es Regente por derecho propio en ningún supuesto.", "No. No existe el cargo de «Presidente de las Cortes Generales»: hay Presidente del Congreso y Presidente del Senado.", "Es esta. El 59.2: reconocida la inhabilitación por las Cortes Generales, entra a ejercer inmediatamente la Regencia el heredero de la Corona, pero solo si es mayor de edad.", "No. Si el heredero es menor de edad se aplica el 59.1: el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder."], "arts": [59], "citas": [{"texto": "«1. Cuando el Rey fuere menor de edad, el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona, según el orden establecido en la Constitución, entrará a ejercer inmediatamente la Regencia y la ejercerá durante el tiempo de la minoría de edad del Rey.»«2. Si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero de la Corona, si fuere mayor de edad. Si no lo fuere, se procederá de la manera prevista en el apartado anterior, hasta que el Príncipe heredero alcance la mayoría de edad.»«3. Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales, y se compondrá de una, tres o cinco personas.» · «4. Para ejercer la Regencia es preciso ser español y mayor de edad.» · «5. La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.»", "fuente": "Artículo 59 CE"}], "truco": "Dos supuestos de Regencia, dos apartados: 59.1 Rey MENOR (padre/madre o pariente más próximo) · 59.2 Rey INHABILITADO (el heredero, si es mayor de edad)."}, {"id": "ce-092", "origen": "otras", "test": "Test exámenes", "n": 101, "enunciado": "En el Título II de la CE, referido a la Corona, se establece que:", "opciones": ["Aquellas personas que, teniendo derecho a la sucesión en el trono, contrajeren matrimonio contra la expresa prohibición del Rey y de las Cortes Generales quedarán excluidas en la sucesión a la Corona por sí y sus descendientes.", "La sucesión en el trono seguirá el orden regular de primogenitura y representación, siendo preferida siempre la línea posterior a la anterior; en la misma línea, el grado más próximo al más remoto; en el mismo grado, el varón a la mujer, y, en el mismo sexo, la persona de más edad a la de menos.", "Corresponde al Rey ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Congreso de los Diputados.", "Al Rey corresponde declarar la guerra y hacer la paz, con el refrendo del Presidente del Congreso de los Diputados."], "bloque": "t2-sucesion", "precepto": "Artículo 57.1 CE; Artículo 57.4 CE", "correcta": 0, "justificaciones": ["Es esta. Reproduce el 57.4 literalmente, incluida la extensión de la exclusión a los descendientes.", "No. Invierte el 57.1: se prefiere «siempre la línea anterior a las posteriores», no la posterior a la anterior.", "No. El 62.g) dice «a petición del Presidente del Gobierno», no del Presidente del Congreso.", "No. El 63.3 exige autorización previa de las Cortes Generales, y el refrendo no corresponde al Presidente del Congreso."], "arts": [57], "citas": [{"texto": "«La Corona de España es hereditaria en los sucesores de S. M. Don Juan Carlos I de Borbón, legítimo heredero de la dinastía histórica. La sucesión en el trono seguirá el orden regular de primogenitura y representación, siendo preferida siempre la línea anterior a las posteriores; en la misma línea, el grado más próximo al más remoto; en el mismo grado, el varón a la mujer, y en el mismo sexo, la persona de más edad a la de menos.»", "fuente": "Artículo 57.1 CE"}, {"texto": "«Aquellas personas que teniendo derecho a la sucesión en el trono contrajeren matrimonio contra la expresa prohibición del Rey y de las Cortes Generales, quedarán excluidas en la sucesión a la Corona por sí y sus descendientes.»", "fuente": "Artículo 57.4 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "El orden sucesorio del 57.1, en cadena: línea anterior antes que posterior → grado más próximo antes que remoto → varón antes que mujer → más edad antes que menos."}, {"id": "ce-093", "origen": "otras", "test": "Test exámenes", "n": 106, "enunciado": "Conforme a la CE corresponde al Rey:", "opciones": ["Nombrar al Defensor del Pueblo a propuesta del Presidente del Gobierno.", "Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales.", "Nombrar al Presidente del Tribunal Constitucional a propuesta del Presidente del Consejo General del Poder Judicial.", "Nombrar a los Delegados del Gobierno a propuesta del Presidente del Gobierno."], "bloque": "t2-rey", "precepto": "Artículo 62 CE", "correcta": 1, "justificaciones": ["No. Al Defensor del Pueblo lo eligen las Cortes Generales (art. 54 CE y art. 2 de la LO 3/1981); el Rey no lo nombra.", "Es esta. Es el 62.i) literal: ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales.", "No. Al Presidente del Tribunal Constitucional lo nombra el Rey a propuesta del propio Tribunal en pleno (art. 160), no del CGPJ.", "No. A los Delegados del Gobierno los nombra el Gobierno (art. 154)."], "arts": [62], "citas": [{"texto": "«Corresponde al Rey: a) Sancionar y promulgar las leyes. b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución. c) Convocar a referéndum en los casos previstos en la Constitución. d) Proponer el candidato a Presidente del Gobierno y, en su caso, nombrarlo, así como poner fin a sus funciones en los términos previstos en la Constitución. e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente. f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes. g) Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno. h) El mando supremo de las Fuerzas Armadas. i) Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales. j) El Alto Patronazgo de las Reales Academias.»", "fuente": "Artículo 62 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-094", "origen": "otras", "test": "Test exámenes", "n": 108, "enunciado": "De conformidad con el artículo 64 de la CE, la propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendadas por:", "opciones": ["El Rey.", "Los Presidentes del Congreso y del Senado.", "El Presidente del Congreso.", "El Rey y los ministros competentes."], "bloque": "t2-rey", "precepto": "Artículo 64 CE", "correcta": 2, "justificaciones": ["No. El Rey no se refrenda a sí mismo: el refrendo es precisamente lo que da validez a sus actos.", "No. El Presidente del Senado no refrenda ningún acto del Rey.", "Es esta. Literal del 64.1: esas dos excepciones las refrenda el Presidente del Congreso.", "No. Los ministros competentes refrendan la regla general, no estas dos excepciones."], "arts": [64], "citas": [{"texto": "«1. Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso. 2. De los actos del Rey serán responsables las personas que los refrenden.»", "fuente": "Artículo 64 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-095", "origen": "otras", "test": "Examen", "n": 4, "enunciado": "¿Quién debe prestar el juramento previsto en el artículo 61 de la Constitución Española de 1978?", "opciones": ["Únicamente el Rey.", "El Rey, el Príncipe heredero y el Regente o Regentes.", "El Rey y todos sus familiares de primer y segundo grado.", "El Rey, el Príncipe heredero, la Reina consorte o el consorte de la Reina y el tutor del Rey menor de edad."], "bloque": "t2-rey", "precepto": "Artículo 61 CE", "correcta": 1, "justificaciones": ["No. No solo el Rey: el 61.2 añade al Príncipe heredero y al Regente o Regentes.", "Es esta. El artículo 61 nombra a tres: el Rey al ser proclamado (61.1), y el Príncipe heredero al alcanzar la mayoría de edad y el Regente o Regentes al hacerse cargo de sus funciones (61.2).", "No. La Constitución no menciona a los familiares del Rey en el artículo 61.", "No. Ni la Reina consorte ni el tutor prestan el juramento del artículo 61."], "arts": [61], "citas": [{"texto": "«1. El Rey, al ser proclamado ante las Cortes Generales, prestará juramento de desempeñar fielmente sus funciones, guardar y hacer guardar la Constitución y las leyes y respetar los derechos de los ciudadanos y de las Comunidades Autónomas.»«2. El Príncipe heredero, al alcanzar la mayoría de edad, y el Regente o Regentes al hacerse cargo de sus funciones, prestarán el mismo juramento, así como el de fidelidad al Rey.»", "fuente": "Artículo 61 CE"}], "truco": "Tres juran: Rey, Príncipe heredero y Regente(s). Y los dos últimos juran algo más que el Rey: fidelidad al Rey. El tutor no jura."}, {"id": "ce-096", "origen": "oficiales", "test": "INAP sept 2023", "n": 34, "enunciado": "En relación con la sucesión en la Corona regulada en el artículo 57 de la CE, extinguidas todas las líneas llamadas en derecho:", "opciones": ["El Gobierno proveerá a la sucesión a la Corona en la forma que más convenga a los intereses de los españoles.", "Las Cortes Generales proveerán a la sucesión a la Corona en la forma que más convenga a los intereses de España.", "El Gobierno proveerá a la sucesión a la Corona en la forma que más convenga a los intereses de España.", "El Congreso de los Diputados proveerá a la sucesión a la Corona en la forma que más convenga a los intereses de los españoles."], "bloque": "t2-sucesion", "precepto": "Artículo 57.3 CE", "correcta": 1, "justificaciones": ["No. Cambia dos cosas: las Cortes por el Gobierno y «España» por «los españoles».", "Es esta. Reproduce el 57.3 palabra por palabra: las Cortes Generales, y «a los intereses de España».", "No. Cambia las Cortes Generales por el Gobierno.", "No. Cambia las Cortes por el Congreso y «España» por «los españoles»."], "arts": [57], "citas": [{"texto": "«Extinguidas todas las líneas llamadas en Derecho, las Cortes Generales proveerán a la sucesión en la Corona en la forma que más convenga a los intereses de España.»", "fuente": "Artículo 57.3 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "ojo": "Cuidado con las variantes que cambian «España» por «los españoles» o las Cortes por el Gobierno."}, {"id": "ce-097", "origen": "otras", "test": "Examen", "n": 9, "enunciado": "De acuerdo con el art 64 de la Constitución Española de 1978 ( en adelante CE), los actos del Rey, excepto la propuesta y el nombramiento del Presidente del Gobierno, y la disolución de las cámaras prevista en en el art 99, serán refrendados por:", "opciones": ["Los Presidentes del Congreso y del Senado", "Los Ministros o Secretarios de Estado en función de la materia", "Siempre por el Presidente del Congreso", "El Presidente del Gobierno y, en su caso, por los Ministros competentes"], "bloque": "t2-rey", "precepto": "Artículo 64 CE", "correcta": 3, "justificaciones": ["No. El Presidente del Senado no refrenda nunca.", "No. Los Secretarios de Estado no refrendan: el 64.1 habla de Ministros.", "No. El Presidente del Congreso solo refrenda las dos excepciones que la propia pregunta acaba de excluir.", "Es esta. Es la regla general del 64.1: el Presidente del Gobierno y, en su caso, los Ministros competentes."], "arts": [64], "citas": [{"texto": "«1. Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso. 2. De los actos del Rey serán responsables las personas que los refrenden.»", "fuente": "Artículo 64 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-098", "origen": "otras", "test": "Examen", "n": 11, "enunciado": "Según el artículo 62 de la Constitución Española de 1978, corresponde al Rey:", "opciones": ["Refrendar los actos del Presidente del Gobierno.", "Controlar la acción del Gobierno.", "Nombrar y separar a los miembros del Gobierno.", "Proponer al Presidente del Gobierno la disolución de las Cortes Generales."], "bloque": "t2-rey", "precepto": "Artículo 62 CE", "correcta": 2, "justificaciones": ["No. El Rey no refrenda: es refrendado (art. 64).", "No. Controlar la acción del Gobierno corresponde a las Cortes Generales (art. 66.2).", "Es esta. Es el 62.e): nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente.", "No. La disolución del artículo 115 la propone el Presidente del Gobierno al Rey, no al contrario."], "arts": [62], "citas": [{"texto": "«Corresponde al Rey: a) Sancionar y promulgar las leyes. b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución. c) Convocar a referéndum en los casos previstos en la Constitución. d) Proponer el candidato a Presidente del Gobierno y, en su caso, nombrarlo, así como poner fin a sus funciones en los términos previstos en la Constitución. e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente. f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes. g) Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno. h) El mando supremo de las Fuerzas Armadas. i) Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales. j) El Alto Patronazgo de las Reales Academias.»", "fuente": "Artículo 62 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-099", "origen": "otras", "test": "Examen", "n": 19, "enunciado": "Señale la afirmación correcta en relación con la Corona, de conformidad con lo establecido en la Constitución Española.", "opciones": ["El Rey sancionará en el plazo de veinte días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará su inmediata publicación.", "El referéndum será convocado por el Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por las Cortes Generales.", "El Príncipe heredero, al alcanzar la mayoría de edad, deberá prestar el mismo juramento que ha de prestar el Regente o Regentes al hacerse cargo de sus funciones.", "Corresponde al Rey presidir, para ser informado de los asuntos de Estado, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Consejo de Ministros."], "bloque": "t2-rey", "precepto": "Artículo 61 CE", "correcta": 2, "justificaciones": ["No. El plazo de sanción es de quince días (art. 91), no de veinte.", "No. El referéndum consultivo lo propone el Presidente del Gobierno con autorización previa del CONGRESO (art. 92.2), no de las Cortes Generales.", "Es esta. Literal del 61.2: el Príncipe heredero al alcanzar la mayoría de edad y el Regente o Regentes al hacerse cargo prestan el mismo juramento.", "No. El 62.g) dice «a petición del Presidente del Gobierno», no del Consejo de Ministros."], "arts": [61], "citas": [{"texto": "«1. El Rey, al ser proclamado ante las Cortes Generales, prestará juramento de desempeñar fielmente sus funciones, guardar y hacer guardar la Constitución y las leyes y respetar los derechos de los ciudadanos y de las Comunidades Autónomas.»«2. El Príncipe heredero, al alcanzar la mayoría de edad, y el Regente o Regentes al hacerse cargo de sus funciones, prestarán el mismo juramento, así como el de fidelidad al Rey.»", "fuente": "Artículo 61 CE"}]}, {"id": "ce-100", "origen": "otras", "test": "Test 2", "n": 25, "enunciado": "De conformidad con el artículo 64 de la CE, ¿quién refrenda la disolución de las Cámaras prevista en el artículo 99?", "opciones": ["El Presidente del Gobierno.", "El Jefe de la Casa Real.", "La Ministra de Justicia.", "El Presidente del Congreso."], "bloque": "t2-rey", "precepto": "Artículo 64 CE", "correcta": 3, "justificaciones": ["No. El Presidente del Gobierno refrenda la regla general, no esta excepción.", "No. El Jefe de la Casa Real no refrenda actos del Rey.", "No. Ningún ministro refrenda la disolución del artículo 99.", "Es esta. Literal del 64.1: la disolución prevista en el artículo 99 la refrenda el Presidente del Congreso."], "arts": [64], "citas": [{"texto": "«1. Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso. 2. De los actos del Rey serán responsables las personas que los refrenden.»", "fuente": "Artículo 64 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "Dos disoluciones, dos refrendos: la del 99 (automática, por no lograrse la investidura en dos meses) la refrenda el Presidente del CONGRESO; la del 115 (la que propone el Presidente del Gobierno) la refrenda el Presidente del GOBIERNO."}, {"id": "ce-101", "origen": "otras", "test": "Test 1", "n": 2, "enunciado": "En España la Corona es un órgano constitucional con unas funciones delimitadas en la Constitución y:", "opciones": ["Separada de los poderes Legislativo y Judicial y sus órganos y ligada al poder Ejecutivo.", "Separadas de los tres poderes del Estado (Ejecutivo, Legislativo y Judicial) y del resto de órganos.", "Separada de los órganos no constitucionales y ligada a los tres poderes del Estado (Ejecutivo, Legislativo y Judicial).", "Ninguna respuesta es correcta."], "bloque": "t2-rey", "precepto": "Artículo 56.1 CE; Artículo 56.3 CE", "correcta": 1, "justificaciones": ["No. No está ligada al ejecutivo: dirigir la política interior y exterior es del Gobierno (art. 97).", "Es esta. La Corona es un órgano constitucional propio, con su Título II, separado de los tres poderes: el Rey no legisla, no gobierna y no juzga. «Arbitra y modera», y sus actos necesitan refrendo.", "No. No está ligada a los tres poderes: los arbitra y modera desde fuera, sin formar parte de ninguno.", "No. Sí hay respuesta correcta: la que separa la Corona de los tres poderes del Estado y del resto de órganos."], "arts": [56], "citas": [{"texto": "«El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones, asume la más alta representación del Estado español en las relaciones internacionales, especialmente con las naciones de su comunidad histórica, y ejerce las funciones que le atribuyen expresamente la Constitución y las leyes.»", "fuente": "Artículo 56.1 CE"}, {"texto": "«La persona del Rey es inviolable y no está sujeta a responsabilidad. Sus actos estarán siempre refrendados en la forma establecida en el artículo 64, careciendo de validez sin dicho refrendo, salvo lo dispuesto en el artículo 65, 2.»", "fuente": "Artículo 56.3 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "La expresión del 56.1 es «arbitra y modera». Modera desde fuera, no desde dentro de ninguno de los tres poderes."}, {"id": "ce-102", "origen": "otras", "test": "Test 1", "n": 5, "enunciado": "La Corona queda regulada en el Título II de la Constitución, que comprende:", "opciones": ["Los artículos 26 a 35.", "Los artículos 36 a 45.", "Los artículos 46 a 55.", "Los artículos 56 a 65."], "bloque": "t2-rey", "precepto": "Constitución Española · Título II", "correcta": 3, "justificaciones": ["No. Los artículos 26 a 35 están en el Título I (Capítulo II).", "No. Los artículos 36 a 45 están también en el Título I.", "No. Los artículos 46 a 55 están en el Título I, que se cierra precisamente con el 55.", "Es esta. El Título II, «De la Corona», empieza en el artículo 56 y acaba en el 65: diez artículos."], "arts": [], "citas": [{"texto": "«TÍTULO II. De la Corona»: abre con el «Artículo 56. 1. El Rey es el Jefe del Estado […]» y cierra con el «Artículo 65. […] 2. El Rey nombra y releva libremente a los miembros civiles y militares de su Casa.»", "fuente": "Constitución Española · Título II"}], "truco": "El Título I acaba en el 55 y el Título II va del 56 al 65: diez artículos justos. El Título III arranca en el 66."}, {"id": "ce-103", "origen": "otras", "test": "Test 1", "n": 6, "enunciado": "La abdicación de D. Juan Carlos fue efectiva con la entrada en vigor, el día 19 de junio de 2014, de:", "opciones": ["La Ley Orgánica 1/2014, de 18 de junio, por la que se hace efectiva la abdicación de Su Majestad el Rey Don Juan Carlos I de Borbón.", "La Ley Orgánica 2/2014, de 18 de junio, por la que se hace efectiva la abdicación de Su Majestad el Rey Don Juan Carlos I de Borbón", "La Ley Orgánica 3/2014, de 18 de junio, por la que se hace efectiva la abdicación de Su Majestad el Rey Don Juan Carlos I de Borbón.", "La Ley Orgánica 4/2014, de 18 de junio, por la que se hace efectiva la abdicación de Su Majestad el Rey Don Juan Carlos I de Borbón."], "bloque": "t2-sucesion", "precepto": "Artículo 57.5 CE", "correcta": 2, "justificaciones": ["No. La LO 1/2014 de ese año no es la de la abdicación.", "No. Tampoco la LO 2/2014.", "Es esta. Ley Orgánica 3/2014, de 18 de junio, por la que se hace efectiva la abdicación de Su Majestad el Rey Don Juan Carlos I de Borbón, en vigor el 19 de junio de 2014, dictada al amparo del 57.5.", "No. Tampoco la LO 4/2014."], "arts": [57], "citas": [{"texto": "«Las abdicaciones y renuncias y cualquier duda de hecho o de derecho que ocurra en el orden de sucesión a la Corona se resolverán por una ley orgánica.»", "fuente": "Artículo 57.5 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "Número y fechas casi encadenados: Ley Orgánica 3/2014, de 18 de junio, efectiva el 19 de junio. Tres, dieciocho, diecinueve."}, {"id": "ce-104", "origen": "otras", "test": "Test 1", "n": 7, "enunciado": "Entre las funciones concretas del Rey no se encuentra:", "opciones": ["Convocar a referéndum en los casos previstos en la Constitución.", "Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución.", "Nombrar y separar a los miembros del Gobierno, a propuesta del Congreso de los Diputados.", "El Alto Patronazgo de las Reales Academias."], "bloque": "t2-rey", "precepto": "Artículo 62 CE", "correcta": 2, "justificaciones": ["No. Sí es función del Rey: 62.c), convocar a referéndum en los casos previstos en la Constitución.", "No. Sí es función del Rey: 62.b).", "Es esta. El 62.e) dice «a propuesta de su Presidente», es decir, del Presidente del Gobierno. Cambiarlo por el Congreso de los Diputados es lo que convierte esta opción en la falsa que pide el enunciado.", "No. Sí es función del Rey: 62.j), el Alto Patronazgo de las Reales Academias."], "arts": [62], "citas": [{"texto": "«Corresponde al Rey: a) Sancionar y promulgar las leyes. b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución. c) Convocar a referéndum en los casos previstos en la Constitución. d) Proponer el candidato a Presidente del Gobierno y, en su caso, nombrarlo, así como poner fin a sus funciones en los términos previstos en la Constitución. e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente. f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes. g) Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno. h) El mando supremo de las Fuerzas Armadas. i) Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales. j) El Alto Patronazgo de las Reales Academias.»", "fuente": "Artículo 62 CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}}, {"id": "ce-105", "origen": "otras", "test": "Test 1", "n": 8, "enunciado": "Para ejercer la Regencia es preciso:", "opciones": ["Ser español y mayor de edad.", "Ser español, mayor de edad y ascendiente del Rey.", "Ser español, mayor de edad, y ascendiente o descendiente del Rey.", "Ser español, mayor de edad y familiar del Rey."], "bloque": "t2-sucesion", "precepto": "Artículo 59 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 59.4: ser español y mayor de edad, sin más requisitos.", "No. El 59.4 no exige ser ascendiente del Rey.", "No. Tampoco exige ser ascendiente ni descendiente.", "No. No se exige parentesco alguno: la Regencia puede recaer en quien nombren las Cortes Generales (59.3)."], "arts": [59], "citas": [{"texto": "«1. Cuando el Rey fuere menor de edad, el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona, según el orden establecido en la Constitución, entrará a ejercer inmediatamente la Regencia y la ejercerá durante el tiempo de la minoría de edad del Rey.»«2. Si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero de la Corona, si fuere mayor de edad. Si no lo fuere, se procederá de la manera prevista en el apartado anterior, hasta que el Príncipe heredero alcance la mayoría de edad.»«3. Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales, y se compondrá de una, tres o cinco personas.» · «4. Para ejercer la Regencia es preciso ser español y mayor de edad.» · «5. La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.»", "fuente": "Artículo 59 CE"}]}, {"id": "ce-154", "origen": "oficiales", "test": "INAP mayo 2026", "n": 2, "enunciado": "Corresponde al Rey, conforme al artículo 62 de la Constitución Española de 1978:", "opciones": ["Aprobar los Decretos Leyes.", "Aprobar los Reglamentos.", "Aprobar las Leyes.", "Sancionar y promulgar las leyes."], "bloque": "t2-rey", "precepto": "Artículo 62 a) CE", "correcta": 3, "justificaciones": ["No. Los decretos-leyes los dicta el Gobierno (86.1) y los convalida o deroga el Congreso.", "No. La potestad reglamentaria es del Gobierno (97 CE).", "No. Las leyes las aprueban las Cortes Generales (66.2); al Rey le llegan ya aprobadas.", "Es esta. El Rey no aprueba nada: sanciona y promulga. Aprobar las leyes es de las Cortes Generales."], "arts": [62], "citas": [{"texto": "«Corresponde al Rey: a) Sancionar y promulgar las leyes.»", "fuente": "Artículo 62 a) CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "El verbo delata la trampa. El Rey sanciona, promulga, convoca, disuelve, nombra, expide, acredita. Nunca «aprueba»."}, {"id": "ce-160", "origen": "oficiales", "test": "INAP julio 2026 (extraordinario)", "n": 2, "enunciado": "Conforme al artículo 62 de la Constitución Española de 1978 corresponde al Rey:", "opciones": ["El mando supremo de la Fuerzas Armadas.", "Dirigir la Administración civil y militar y la defensa del Estado.", "Proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana.", "Declarar la guerra y hacer la paz, previa autorización del Gobierno."], "bloque": "t2-rey", "precepto": "Artículo 62 h) CE", "correcta": 0, "justificaciones": ["Es esta. El mando supremo es del Rey, y está en la letra h) del 62.", "No. Dirigir la Administración civil y militar y la defensa del Estado es del Gobierno (97 CE).", "No. Proteger el libre ejercicio de los derechos y garantizar la seguridad ciudadana es la misión de las Fuerzas y Cuerpos de Seguridad (104.1).", "No. Declarar la guerra y hacer la paz sí es del Rey, pero previa autorización de **las Cortes Generales** (63.3), no del Gobierno."], "arts": [62], "citas": [{"texto": "«Corresponde al Rey: h) El mando supremo de las Fuerzas Armadas.»", "fuente": "Artículo 62 h) CE"}], "marca": {"nivel": "clave", "nota": "De la Corona, lo que más cae: el Rey como Jefe del Estado, el orden de sucesión, sus funciones del artículo 62 y el refrendo."}, "truco": "Mandar no es dirigir: el Rey tiene el mando supremo (62 h) y el Gobierno dirige la defensa (97). Las dos frases son verdad y no se contradicen."}, {"id": "ce-170", "origen": "oficiales", "test": "INAP sept 2025", "n": 3, "enunciado": "De acuerdo con el artículo 63 de la Constitución Española de 1978, ¿a quién corresponde declarar la guerra y hacer la paz?", "opciones": ["Al Gobierno, previa autorización del Rey.", "Al Congreso de los Diputados, previa autorización del Rey.", "Al Rey, previa autorización de las Cortes Generales.", "Al Rey, previa autorización del Congreso de los Diputados."], "bloque": "t2-rey", "precepto": "Artículo 63.3 CE", "correcta": 2, "justificaciones": ["No. El Gobierno no declara la guerra, y quien autoriza no es el Rey.", "No. Tampoco es el Congreso quien declara.", "Es esta. Declara el Rey, autorizan las Cortes Generales: las dos Cámaras.", "No. El Congreso solo no basta: el 63.3 exige la autorización de las Cortes Generales, es decir, de las dos Cámaras."], "arts": [63], "citas": [{"texto": "«Al Rey corresponde, previa autorización de las Cortes Generales, declarar la guerra y hacer la paz.»", "fuente": "Artículo 63.3 CE"}], "truco": "Cuidado con «Cortes Generales» frente a «Congreso». En la guerra son las dos Cámaras; en los estados excepcionales del 116, en cambio, todo pasa por el Congreso."}, {"id": "ce-177", "origen": "oficiales", "test": "INAP 2025 (extraordinario)", "n": 2, "enunciado": "Según el artículo 65.2 de la Constitución Española de 1978:", "opciones": ["El Rey nombra y releva libremente a los miembros civiles y militares de su Casa.", "El Gobierno nombra y releva libremente a los miembros civiles y militares de la Casa del Rey.", "El Ministro de Presidencia nombra y releva a los miembros civiles de la Casa del Rey y el Ministro de Defensa a los Miembros militares.", "El Parlamento nombra y releva a los miembros civiles y militares de la Casa del Rey a propuesta del Gobierno."], "bloque": "t2-rey", "precepto": "Artículo 65.2 CE", "correcta": 0, "justificaciones": ["Es esta. Libremente y él solo: es una de las poquísimas cosas que el Rey hace sin refrendo.", "No. El Gobierno no nombra a la Casa del Rey.", "No. Ningún ministro reparte esos nombramientos.", "No. El Parlamento no interviene."], "arts": [65], "citas": [{"texto": "«El Rey nombra y releva libremente a los miembros civiles y militares de su Casa.»", "fuente": "Artículo 65.2 CE"}], "truco": "El 56.3 dice que todos los actos del Rey van refrendados «salvo lo dispuesto en el artículo 65.2». Ese es el hueco: la Casa del Rey y el reparto de la asignación presupuestaria (65.1)."}, {"id": "ce-193", "origen": "oficiales", "test": "INAP dic 2023", "n": 13, "enunciado": "De conformidad con el Título II de la Constitución Española de 1978, señala la respuesta CORRECTA:", "opciones": ["Corresponde al Rey declarar la guerra y hacer la paz, previa autorización del Congreso de los Diputados.", "El Rey ejerce el derecho de gracia con arreglo a la ley, que podrá autorizar indultos generales.", "El Rey recibe de los Presupuestos del Estado una cantidad global para el sostenimiento de su Familia y Casa, y distribuye libremente la misma.", "El Rey presta el consentimiento del Estado para obligarse por medio de tratados."], "bloque": "t2-rey", "precepto": "Artículo 65.1 CE", "correcta": 2, "justificaciones": ["No. La autorización para declarar la guerra y hacer la paz es de las **Cortes Generales** (63.3), no del Congreso.", "No. El 62 i) dice justo lo contrario: la ley **no** podrá autorizar indultos generales.", "Es esta. Cantidad global y reparto libre: el 65.1, palabra por palabra.", "No. El 63.2 dice que al Rey corresponde manifestar el consentimiento del Estado, «de conformidad con la Constitución y las leyes»: y en los casos del 94.1 hace falta autorización previa de las Cortes. La opción lo presenta como si el Rey lo prestara sin más."], "arts": [65], "citas": [{"texto": "«El Rey recibe de los Presupuestos del Estado una cantidad global para el sostenimiento de su Familia y Casa, y distribuye libremente la misma.»", "fuente": "Artículo 65.1 CE"}], "truco": "Dentro del Título II, el 65 es el artículo del dinero y de la Casa: asignación global que reparte libremente y nombramiento libre de los miembros de su Casa. Son las dos cosas que hace sin refrendo."}, {"id": "ce-257", "origen": "otras", "test": "Examen Tema 3", "n": 12, "enunciado": "Según el artículo 59 de la CE, si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia:", "opciones": ["El Presidente del Gobierno.", "El Príncipe heredero de la Corona, si fuere mayor de edad.", "El Príncipe heredero de la Corona, aunque fuese menor de edad.", "La Reina Regente."], "bloque": "t2-sucesion", "precepto": "Artículo 59.2 CE", "correcta": 1, "justificaciones": ["No. El Presidente del Gobierno no ejerce la Regencia en ningún supuesto del artículo 59.", "Es esta. Literal del 59.2: el Príncipe heredero asume la Regencia si es mayor de edad; si no lo es, rige el régimen del apartado anterior (padre, madre o pariente más próximo) hasta que alcance la mayoría de edad.", "No. Si el Príncipe heredero fuese menor de edad, la Regencia la ejerce quien prevé el apartado 1 (padre, madre o pariente más próximo), no el Príncipe menor.", "No. «Reina Regente» no es una figura de este apartado: la Regencia del cónyuge del Rey no está prevista en el 59."], "arts": [59], "citas": [{"texto": "«Si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero de la Corona, si fuere mayor de edad. Si no lo fuere, se procederá de la manera prevista en el apartado anterior, hasta que el Príncipe heredero alcance la mayoría de edad.»", "fuente": "Artículo 59.2 CE"}]}]});
